}

@Observable
@MainActor
public final class SettingsViewModel {
    public var uiTheme: UITheme = .default
    public var defaultEngine: TranscriptionEngineKey = TranscriptionConfig.default.defaultEngine
    public var autoRecordEnabled = false
    public var startDebounce = 3.0
    public var stopDebounce = 10.0
    public var defaultMeetingType: MeetingType = SummaryConfig.default.meetingType
    public var translationEnabled = false
    public var sourceLanguage = "en"
    public var targetLanguage = "es"
    public var cacheTTLHours = 24
    public var semanticCacheDays = 7
    public var maxCacheEntries = 1000
    public var defaultExportFormat: ShareFormat = .markdown
    public var speakerProfiles: [SpeakerProfile] = []
    public var errorMessage: String?
    public var buildID = "unknown"
    public var recentLogs: [String] = []
    public var privacyMode: PrivacyMode = AppConfig.default.privacyMode

    // Integrations (F21 E5)
    public var isNotionEnabled = false
    public var obsidianVaultPath = ""

    // Storage (#124)
    public var totalRecordingsBytes: Int64?
    public var availableDiskBytes: Int64?
    public var autoDeleteEnabled = false
    public var autoDeleteOlderThanDays: Int = 30

    /// Delete All Data (#123)
    /// The text the user types into the confirmation field before the delete-all action runs.
    public var deleteAllConfirmationText: String = ""
    /// `true` while the erase operation is in flight.
    public var isDeletingAllData: Bool = false
    /// Log of resource labels successfully erased in the last delete-all run.
    public var deleteAllDataLog: [String] = []
    /// Set to `true` by the recording state observer while a recording is active.
    public var isRecordingActive: Bool = false

    /// Archive Pass
    public var archivePassEnabled: Bool = true {
        didSet {
            NotificationCenter.default.post(
                name: .archivePassEnabledChanged,
                object: nil,
                userInfo: ["enabled": archivePassEnabled]
            )
        }
    }

    // Audio device selection
    public var tapAllAudio = true
    public var echoCancellationEnabled = true
    public var outputDevices: [AudioDevice] = []
    public var inputDevices: [AudioDevice] = []
    public var selectedOutputDeviceID = ""
    public var selectedInputDeviceID = ""

    // Dependencies (internal so extension files can reach them)
    let profileStore: (any SpeakerProfileStore)?
    let audioDeviceConfigStore: (any AudioDeviceConfigStore)?
    let deviceEnumeration: (any AudioDeviceEnumeration)?
    let currentThemeProvider: () -> UITheme
    let currentEngineProvider: () -> TranscriptionEngineKey
    let recordingReadRepository: (any RecordingReadRepository)?
    let diskSpaceMonitor: (any DiskSpaceMonitor)?

    public init(
        profileStore: (any SpeakerProfileStore)? = nil,
        audioDeviceConfigStore: (any AudioDeviceConfigStore)? = nil,
        deviceEnumeration: (any AudioDeviceEnumeration)? = nil,
        currentThemeProvider: @escaping () -> UITheme = { .default },
        currentEngineProvider: @escaping () -> TranscriptionEngineKey = { TranscriptionConfig.default.defaultEngine },
        recordingReadRepository: (any RecordingReadRepository)? = nil,
        diskSpaceMonitor: (any DiskSpaceMonitor)? = nil
    ) {
        self.profileStore = profileStore
        self.audioDeviceConfigStore = audioDeviceConfigStore
        self.deviceEnumeration = deviceEnumeration
        self.currentThemeProvider = currentThemeProvider
        self.currentEngineProvider = currentEngineProvider
        self.recordingReadRepository = recordingReadRepository
        self.diskSpaceMonitor = diskSpaceMonitor
    }

    public func loadCurrentTheme() {
        uiTheme = currentThemeProvider()
    }

    public func loadCurrentEngine() {
        defaultEngine = currentEngineProvider()
    }

    public func saveEngine() {
        NotificationCenter.default.post(
            name: .engineChanged,
            object: nil,
            userInfo: ["defaultEngine": defaultEngine.rawValue]
        )
    }

    public func saveTheme() {
        NotificationCenter.default.post(
            name: .themeChanged,
            object: nil,
            userInfo: ["uiTheme": uiTheme]
        )
    }

    public func applyPrivacyMode() {
        NotificationCenter.default.post(
            name: .privacyModeChanged,
            object: nil,
            userInfo: ["privacyMode": privacyMode.rawValue]
        )
    }

    public func refreshDiagnostics() {
        buildID = Bundle.main.object(forInfoDictionaryKey: "CFBundleVersion") as? String
            ?? Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String
            ?? "unknown"
        recentLogs = ErrorLog.shared.recentEntries
    }
}

import Domain
import FluidAudio
import Foundation
import Logging
import Utilities

// MARK: - ParakeetPlugin

/// FluidAudio/Parakeet TDT transcription engine (Apple Silicon optimised).
///
/// ## Thread Safety
/// All mutable state (`asrManager`, `loadedModelId`, `sequenceCounter`) is
/// actor-isolated. `AsrManager` is itself an actor; all calls to it cross
/// isolation boundaries via `await`.
///
/// ## Decoder State
/// A fresh `TdtDecoderState` is created per `transcribe` call, making each
/// invocation stateless. This is appropriate for batch/chunk processing where
/// the caller manages session continuity via `TranscriptionContext`.
///
/// ## warm-up
/// `warmUp()` is a no-op: `AsrManager` prewarms its CoreML models during
/// `initialize` / `loadModels`. No additional pass is needed.
public actor ParakeetPlugin: TranscriptionEngine {
    // MARK: - Actor State

    private var asrManager: AsrManager?
    private var loadedModelId: ModelID?
    private var sequenceCounter = 0
    public private(set) var downloadDelegate: (any ModelDownloadDelegate)?

    private let logger = AppLogger.for(category: "Parakeet")

    // MARK: - Init

    public init() {}

    public func setDownloadDelegate(_ delegate: (any ModelDownloadDelegate)?) {
        downloadDelegate = delegate
    }

    // MARK: - TranscriptionEngine

    public func loadModel(_ modelId: ModelID) async throws {
        if loadedModelId == modelId, asrManager != nil {
            logger.info("Parakeet model already loaded — skipping")
            return
        }

        logger.info("Loading Parakeet model '\(modelId, privacy: .public)'")
        await downloadDelegate?.downloadProgress(
            .init(modelId: modelId, fractionCompleted: 0.0, phase: .downloading)
        )

        do {
            let models = try await withTimeout(TimeoutConfig.modelLoad) {
                try await AsrModels.downloadAndLoad(version: .v3)
            }

            await downloadDelegate?.downloadProgress(
                .init(modelId: modelId, fractionCompleted: 0.6, phase: .compiling)
            )

            let tdtConfig = TdtConfig(blankId: AsrModelVersion.v3.blankId)
            let asrConfig = ASRConfig(
                tdtConfig: tdtConfig,
                encoderHiddenSize: AsrModelVersion.v3.encoderHiddenSize
            )
            let manager = AsrManager(config: asrConfig)
            try await manager.loadModels(models)

            asrManager = manager
            loadedModelId = modelId

            await downloadDelegate?.downloadProgress(
                .init(modelId: modelId, fractionCompleted: 1.0, phase: .ready)
            )
            logger.info("Parakeet model '\(modelId, privacy: .public)' loaded")
        } catch {
            asrManager = nil
            loadedModelId = nil
            let errDesc = String(reflecting: error)
            logger.error("Parakeet load error: \(errDesc, privacy: .private)")
            throw TranscriptionError.modelNotLoaded(underlying: error)
        }
    }

    public func transcribe(
        samples: [Float],
        context: TranscriptionContext
    ) async throws -> Domain.TranscriptionSegment {
        guard !samples.isEmpty else {
            throw TranscriptionError.audioTooShort
        }
        guard let manager = asrManager else {
            throw TranscriptionError.modelNotLoaded(underlying: nil)
        }

        let sid = context.sessionId?.rawValue ?? "none"
        // swiftlint:disable:next line_length
        logger.debug("Parakeet transcribing \(samples.count, privacy: .public) samples | session: \(sid, privacy: .private)")

        let result: ASRResult
        let profiler = HardwareBoundaryProfiler(category: "Performance")
        let token = await profiler.begin("Parakeet Inference")

        do {
            let layers = await manager.decoderLayerCount
            var decoderState = TdtDecoderState.make(decoderLayers: layers)
            result = try await manager.transcribe(samples, decoderState: &decoderState)
            await profiler.end(token)
        } catch {
            await profiler.end(token)
            let errDesc = String(reflecting: error)
            logger.error("Parakeet inference error: \(errDesc, privacy: .private)")
            throw TranscriptionError.inferenceFailed(underlying: error)
        }

        let seqNum = sequenceCounter
        sequenceCounter += 1
        return buildSegment(result: result, context: context, sequenceNumber: seqNum)
    }

    public func isReady() async -> Bool {
        asrManager != nil
    }

    /// No-op: Parakeet models are warm after `AsrManager.loadModels(_:)`.
    public func warmUp() async throws {}

    // MARK: - Private Helpers

    private func buildSegment(
        result: ASRResult,
        context: TranscriptionContext,
        sequenceNumber: Int
    ) -> Domain.TranscriptionSegment {
        let startTime = context.timestampOffset
        let endTime = startTime + result.duration
        let confidence = min(1.0, max(0.0, Double(result.confidence)))

        return Domain.TranscriptionSegment(
            id: .generate(),
            text: result.text,
            startTime: startTime,
            endTime: endTime,
            confidence: confidence,
            isFinal: context.isFinalChunk,
            sequenceNumber: sequenceNumber
        )
    }
}

import AppKit
import AudioInfrastructure
import Business
import Domain
import Foundation
import MLInfrastructure
import OSLog
import Presentation
import Utilities
import RecordPro

// MARK: - Builder Methods

@MainActor
extension AppAssembler {

    // MARK: - Storage

    // swiftlint:disable:next function_body_length
    func buildStorage() async -> (reader: DuckDBReaderActor, writer: DuckDBWriterActor) {
        let isTest = ProcessInfo.processInfo.environment["XCTestConfigurationFilePath"] != nil
            || ProcessInfo.processInfo.processName.lowercased().contains("test")
            || ProcessInfo.processInfo.processName.lowercased().contains("xctest")

        let reader: DuckDBReaderActor
        let writer: DuckDBWriterActor
        do {
            let r = try await Task.detached {
                try isTest ? DuckDBReaderActor(databasePath: nil) : DuckDBReaderActor()
            }.value
            let db = await r.database
            let w = try await Task.detached {
                try DuckDBWriterActor(database: db)
            }.value
            reader = r
            writer = w
            if !isTest {
                let server = DuckDBCommandServer(storage: writer)
                commandServer = server
                taskBag.add(Task { await server.start() })
            }
        } catch {
            let errDesc = String(reflecting: error)
            logger
                .critical(
                    "DuckDB initialization failed: \(errDesc, privacy: .public) — falling back to in-memory storage",
                )
            do {
                let r = try await Task.detached {
                    try DuckDBReaderActor(databasePath: nil)
                }.value
                let db = await r.database
                let w = try await Task.detached {
                    try DuckDBWriterActor(database: db)
                }.value
                reader = r
                writer = w
                await showFatalAlert(error: error)
            } catch let fallbackError {
                let fbDesc = String(reflecting: fallbackError)
                logger
                    .critical(
                        "DuckDB fallback also failed: \(fbDesc, privacy: .public) — terminating via NSApp.terminate",
                    )
                await showFatalAlert(error: fallbackError)
                // Wait indefinitely because the alert terminates the app
                do { try await Task.sleep(nanoseconds: 10_000_000_000) } catch {}
                // Application will terminate from the alert, so we just return dummy instances or exit safely
                exit(1)
            }
        }

        // DuckDB is single-writer-per-file. Each actor owns an independent file:
        //   therecord.duckdb     → DuckDBStorageActor   (recordings + segments)
        //   commitments.duckdb → DuckDBCommitmentStore (commitments)
        let commitmentStore: DuckDBCommitmentStore?
        do {
            commitmentStore = try await Task.detached {
                if isTest {
                    return try DuckDBCommitmentStore(databasePath: nil)
                } else {
                    let dbDir = Directories.appSupport
                    try Directories.ensureDirectory(at: dbDir)
                    let dbURL = dbDir.appendingPathComponent(AppConstants.Paths.commitmentsDatabaseFileName)
                    return try DuckDBCommitmentStore(databasePath: dbURL)
                }
            }.value
        } catch {
            let errDesc = String(reflecting: error)
            // swiftlint:disable:next log_localized_description_at_error
            logger.error("Failed to init DuckDBCommitmentStore: \(errDesc, privacy: .public)")
            commitmentStore = nil
        }

        trackCommitmentsUseCase = commitmentStore.map { TrackCommitmentsUseCase(store: $0) }
        return (reader, writer)
    }

    /// Shows a fatal database-error alert, activates an existing instance if found,
    /// and terminates the app. Extracted to deduplicate the two identical alert blocks
    /// in `buildStorage`.
    @MainActor
    private func showFatalAlert(error: any Error) {
        let alert = NSAlert()
        alert.messageText = "THE RECORD could not start"
        // swiftlint:disable:next line_length
        alert.informativeText = "Failed to initialise the database: \(error.localizedDescription). If THE RECORD is already running, quit it and try again."
        alert.alertStyle = .warning
        alert.addButton(withTitle: "OK")
        alert.runModal()
        if let existing = NSRunningApplication.runningApplications(
            withBundleIdentifier: AppConstants.Bundle.identifier,
        ).first(where: { $0 != .current }) {
            existing.activate()
        }
        NSApp.terminate(nil)
    }

    // MARK: - Engine

    func buildEngine(
        config: AppConfig,
        fallbackTrack: TrackCommitmentsUseCase,
        alignment: (any AlignmentUseCase)? = nil,
        // swiftlint:disable:next large_tuple
    ) -> (TrackCommitmentsUseCase, TheRecordEngine, ContextSuggestionsViewModel, QueryContextUseCase) {
        let classifyUseCase = ClassifySegmentUseCase(classifier: OnDeviceNLPPlugin())
        let providers = buildMCPProviders(config: config)
        let queryContext = QueryContextUseCase()
        let engine = TheRecordEngine(
            classify: classifyUseCase,
            track: fallbackTrack,
            query: queryContext,
            providers: providers,
            alignment: alignment,
        )
        let suggestionsVM = ContextSuggestionsViewModel()
        return (fallbackTrack, engine, suggestionsVM, queryContext)
    }

    func buildMCPProviders(config: AppConfig) -> [any ContextProvider] {
        guard config.mcpConsentGranted else { return [] }

        // Try to create a context cache for semantic caching of query results.
        // If cache initialization fails, providers will work without caching.
        let contextCache: DuckDBContextCache?
        do {
            contextCache = try DuckDBContextCache(databasePath: nil)
        } catch {
            let errDesc = String(reflecting: error)
            logger.warning("Failed to initialize context cache: \(errDesc, privacy: .public)")
            contextCache = nil
        }

        // Migrate Keychain accessibility for existing credentials (no-op on clean install).
        let credentialStore = KeychainCredentialStore()
        try? credentialStore.migrateAccessibilityIfNeeded()

        var providers: [any ContextProvider] = []

        // Generic MCP endpoint providers (configured via mcpEndpoints).
        for endpoint in config.mcpEndpoints {
            let isLocal = endpoint.url.host == "localhost" || endpoint.url.host == "127.0.0.1"
            guard endpoint.url.scheme == "https" || isLocal else { continue }
            let provider = GenericMCPProvider(endpoint: endpoint.url, providerID: endpoint.providerID)
            providers.append(provider)
        }

        // Notion provider: constructed when the user has enabled the Notion integration.
        if config.notionEnabled {
            providers.append(NotionProvider(credentialStore: credentialStore))
        }

        // Obsidian provider: constructed when the user has configured a vault path.
        if let vaultPath = config.obsidianVaultPath, !vaultPath.isEmpty {
            providers.append(ObsidianProvider(vaultPath: URL(fileURLWithPath: vaultPath)))
        }

        // Wrap every provider in the caching layer when a cache is available.
        guard let cache = contextCache else { return providers }
        let cacheConfig = config.contextCache
        return providers.map { provider in
            CachingContextProvider(
                inner: provider,
                cache: cache,
                ttlSeconds: cacheConfig.exactTTLSeconds,
                semanticTTLSeconds: cacheConfig.semanticTTLSeconds,
                semanticThreshold: cacheConfig.semanticThreshold,
                maxEntries: cacheConfig.maxEntries,
            )
        }
    }

    // MARK: - Library VM

    func buildLibraryVM(
        reader: DuckDBReaderActor,
        writer: DuckDBWriterActor,
    ) -> (MeetingLibraryViewModel, Task<Void, Never>) {
        let libVM = MeetingLibraryViewModel(storage: reader)
        let migrationTask = Task<Void, Never> {
            do {
                let migrated = try await JSONMigrationHelper.migrate(
                    from: Directories.appSupport, reader: reader, writer: writer,
                )
                if migrated > 0 { logger.info("Migrated \(migrated, privacy: .public) recordings to DuckDB") }
            } catch {
                let errDesc = String(reflecting: error)
                logger.error("Migration failed: \(errDesc, privacy: .public)")
                await MainActor.run { libVM.errorMessage = "Migration failed: \(error.localizedDescription)" }
            }
        }
        return (libVM, migrationTask)
    }

    // MARK: - MenuBar VM

    // sequential setup — extraction would harm readability
    // swiftlint:disable:next function_parameter_count
    func buildMenuBarVM(
        reader: DuckDBReaderActor,
        writer: DuckDBWriterActor,
        engine: TheRecordEngine,
        suggestionsVM: ContextSuggestionsViewModel,
        migrationTask: Task<Void, Never>,
        config: AppConfig,
        queryContext: QueryContextUseCase,
        enableCoreAudioListeners: Bool = true,
    ) -> MenuBarViewModel {
        let audio = AudioSubAssembler().build(
            reader: reader, writer: writer, config: config, queryContext: queryContext,
        )
        let transcription = TranscriptionSubAssembler().build(
            reader: reader, writer: writer, audioCapture: audio.audioCapture, config: config,
        )
        transcriptionBuilt = transcription
        let audioDetector = AudioSessionDetector(
            selfRecordingProvider: audio.audioCapture,
            autoListen: enableCoreAudioListeners,
        )
        let eventKit = EventKitPlugin()
        let meetingDetector = CalendarAwareMeetingDetector(
            calendar: eventKit,
            audioDetector: audioDetector,
        )
        let pipelineCoordinator = PipelineCoordinator(
            cleanupTranscribe: transcription.cleanupUseCase,
            diarizeMeeting: transcription.diarizeUseCase,
            summarizeMeeting: transcription.summarizeUseCase,
            primaryEngine: transcription.primaryEngine,
        )
        Task {
            for await notification in NotificationCenter.default.notifications(named: .archivePassEnabledChanged) {
                guard let enabled = notification.userInfo?["enabled"] as? Bool else { continue }
                await pipelineCoordinator.updateArchivePassEnabled(enabled)
            }
        }
        var deps = MenuBarViewModel.Dependencies(
            startRecording: audio.startUseCase,
            stopAndTranscribe: transcription.stopUseCase,
            pipelineCoordinator: pipelineCoordinator,
            deleteRecording: DeleteRecordingUseCase(storage: writer),
            searchRecordings: SearchRecordingsUseCase(storage: reader),
            autoCleanup: audio.autoCleanup,
            exportAudio: ExportAudioUseCase(storage: reader, exportEngine: AVFoundationExporter()),
            migrationTask: migrationTask,
            engine: engine,
            contextSuggestionsVM: suggestionsVM,
            streamingTranscription: transcription.streamingUseCase,
            liveTranscriptionVM: transcription.liveTranscriptionVM,
            waveformVM: audio.waveformVM,
            liveTranslation: transcription.liveTranslateUseCase,
            listUpcomingMeetings: ListUpcomingMeetingsUseCase(calendar: eventKit),
            micAECProcessor: audio.aecProcessor,
            sleepAssertionService: IOKitSleepAssertionService(),
        )
        // epic-28 / task-003: AEC toggle + cleaned-WAV sink wiring
        deps.cleanedAudioSinkFactory = audio.cleanedAudioSinkFactory
        deps.echoCancellationEnabled = config.audioCapture.echoCancellationEnabled
        deps.cleanedMicPathWriter = writer
        return MenuBarViewModel(dependencies: deps)
    }
}

import AppKit
import Foundation
import Logging
import Domain
import AudioInfrastructure
import MLInfrastructure
import Business
import Presentation
import RecordPro

/// Single composition root for THE RECORD.
///
/// Owns all long-lived infrastructure objects and constructs the full
/// dependency graph when `assemble(config:)` is called.
@MainActor
final class AppAssembler {

    struct Assembled {
        let menuBarVM: MenuBarViewModel
        let libraryVM: MeetingLibraryViewModel
        let searchVM: SearchViewModel
        let detailVM: MeetingDetailViewModel
        let commitmentsVM: CommitmentsViewModel
        let contextSuggestionsVM: ContextSuggestionsViewModel
        let migrationTask: Task<Void, Never>
    }

    // Long-lived infrastructure — must outlive all VMs.
    var reader: DuckDBReaderActor?
    var writer: DuckDBWriterActor?
    var commandServer: DuckDBCommandServer? // periphery:ignore — retained to keep server alive
    var trackCommitmentsUseCase: TrackCommitmentsUseCase?
    var transcriptionBuilt: TranscriptionSubAssembler.Built?

    let logger = AppLogger.for(category: "AppAssembler")

    // Retained so assemble() can be called again without leaking the previous loop.
    var searchSyncTask: Task<Void, Never>?
    var taskBag = TaskBag()

    /// Stops long-lived infrastructure that requires explicit teardown.
    /// Call from `applicationWillTerminate` (#44).
    func teardown() {
        transcriptionBuilt?.prewarmTask.cancel()
        searchSyncTask?.cancel()
        if let server = commandServer {
            Task { await server.stop() }
        }
    }

    // sequential setup — extraction would harm readability
    // swiftlint:disable:next function_body_length
    func assemble(config: AppConfig, enableCoreAudioListeners: Bool = true) async -> Assembled {
        taskBag = TaskBag()
        let st = await buildStorage()
        // Resolve the commitment use case once — both engine and VM share the same instance.
        // If buildStorage() set trackCommitmentsUseCase, use it; otherwise create a single fallback.
        let sharedTrackUseCase = trackCommitmentsUseCase ?? TrackCommitmentsUseCase(store: InMemoryCommitmentStore())
        // Construct alignment use case before buildEngine so it can be injected into TheRecordEngine.
        // AlignTranscriptUseCase is Pro-tier; TheRecordEngine accepts it as (any AlignmentUseCase)?.
        let alignUseCase = AlignTranscriptUseCase(
            sampleLoader: AudioFileLoader(),
            reader: st.reader,
            writer: st.writer,
        )
        let (_, engine, suggestionsVM, queryContext) = buildEngine(
            config: config,
            fallbackTrack: sharedTrackUseCase,
            alignment: alignUseCase,
        )
        let (libVM, migrationTask) = buildLibraryVM(reader: st.reader, writer: st.writer)
        let menuBarVM = buildMenuBarVM(
            reader: st.reader, writer: st.writer, engine: engine, suggestionsVM: suggestionsVM,
            migrationTask: migrationTask, config: config, queryContext: queryContext,
            enableCoreAudioListeners: enableCoreAudioListeners,
        )

        // Recovery fires AFTER menuBarVM is wired so each pending session can be
        // re-transcribed and fed into the diarization + summarization pipeline.
        // Sessions are recovered sequentially to avoid @Observable state races.
        taskBag.add(Task {
            do {
                let ids = try await RecoverPendingSessionsUseCase(storage: st.reader)()
                for id in ids {
                    await menuBarVM.recoverPendingSession(id)
                }
            } catch {
                let errDesc = String(reflecting: error)
                logger.error("Crash recovery check failed: \(errDesc, privacy: .public)")
            }
        })

        let commitmentsVM = CommitmentsViewModel(useCase: sharedTrackUseCase)
        let detailVM = MeetingDetailViewModel(reader: st.reader, writer: st.writer)
        let searchVM = SearchViewModel(
            searchUseCase: SearchRecordingsUseCase(storage: st.reader),
            libraryViewModel: libVM
        )

        // Keep searchVM.meetings in sync with libraryVM whenever it reloads (#85).
        searchSyncTask?.cancel()
        // swiftlint:disable:next task_reassign_without_cancel
        searchSyncTask = Task { @MainActor [weak libVM, weak searchVM] in
            while !Task.isCancelled {
                guard let libVM, let searchVM else { return }
                // OSAllocatedUnfairLock shares the continuation safely between the
                // onChange callback (fires on mutation thread) and onCancel (fires on
                // cancelling thread) so both paths resume it exactly once.
                let slot = OSAllocatedUnfairLock(
                    initialState: CheckedContinuation<Void, Never>?.none,
                )
                await withTaskCancellationHandler {
                    await withCheckedContinuation { (continuation: CheckedContinuation<Void, Never>) in
                        slot.withLock { $0 = continuation }
                        withObservationTracking {
                            searchVM.meetings = libVM.meetings
                        } onChange: {
                            slot.withLock { c in c?.resume()
                                c = nil
                            }
                        }
                    }
                } onCancel: {
                    slot.withLock { c in c?.resume()
                        c = nil
                    }
                }
            }
        }

        return Assembled(
            menuBarVM: menuBarVM,
            libraryVM: libVM,
            searchVM: searchVM,
            detailVM: detailVM,
            commitmentsVM: commitmentsVM,
            contextSuggestionsVM: suggestionsVM,
            migrationTask: migrationTask,
        )
    }

}

