import Foundation
import Logging
import Domain

public actor PipelineCoordinator {

    // TODO: These should be private once BroadsheetAppStatePipeline routes through coordinator methods
    // instead of calling sub-use-cases directly. See GitHub issue filed by swift-4agent review.
    public let cleanupTranscribe: CleanupTranscriptionUseCase
    public let diarizeMeeting: DiarizeMeetingUseCase
    public let summarizeMeeting: SummarizeMeetingUseCase
    private let logger = AppLogger.for(category: "PipelineCoordinator")

    private var pipelineTask: Task<Void, Never>?
    private var cleanupTask: Task<Void, Never>?
    private var pipelineGeneration = 0

    // Instead of directly updating a state, we use closures to push state back to the UI.
    private var onCleanupStateChanged: (@Sendable (CleanupState) -> Void)?
    private var onPipelineStateChanged: (@Sendable (PipelineState) -> Void)?
    private var onPipelineError: (@Sendable (String) -> Void)?

    public func setOnCleanupStateChanged(_ handler: @escaping @Sendable (CleanupState) -> Void) {
        self.onCleanupStateChanged = handler
    }

    public func setOnPipelineStateChanged(_ handler: @escaping @Sendable (PipelineState) -> Void) {
        self.onPipelineStateChanged = handler
    }

    public func setOnPipelineError(_ handler: @escaping @Sendable (String) -> Void) {
        self.onPipelineError = handler
    }

    private var activeRecordingId: RecordingID?
    private let primaryEngine: (any TranscriptionEngine)?
    private let physicalMemory: UInt64
    private var archivePassEnabled: Bool

    private static let memoryUnloadThreshold: UInt64 = 12_000_000_000

    public init(
        cleanupTranscribe: CleanupTranscriptionUseCase,
        diarizeMeeting: DiarizeMeetingUseCase,
        summarizeMeeting: SummarizeMeetingUseCase,
        primaryEngine: (any TranscriptionEngine)? = nil,
        physicalMemory: UInt64 = UInt64(ProcessInfo.processInfo.physicalMemory),
        archivePassEnabled: Bool = true,
    ) {
        self.cleanupTranscribe = cleanupTranscribe
        self.diarizeMeeting = diarizeMeeting
        self.summarizeMeeting = summarizeMeeting
        self.primaryEngine = primaryEngine
        self.physicalMemory = physicalMemory
        self.archivePassEnabled = archivePassEnabled
    }

    public func updateArchivePassEnabled(_ enabled: Bool) {
        archivePassEnabled = enabled
    }

    public func cancelAll() {
        pipelineTask?.cancel()
        cleanupTask?.cancel()
        pipelineGeneration &+= 1
        activeRecordingId = nil
        onPipelineStateChanged?(.idle)
        onCleanupStateChanged?(.idle)
    }

    public func recoverPendingSession(_ recordingId: RecordingID) async {
        guard archivePassEnabled else { return }
        logger.info("Recovering pending session: \(recordingId, privacy: .private)")
        guard let result = await performCleanupTranscription(recordingId: recordingId) else {
            logger.error("Recovery transcription failed — session stays pending: \(recordingId, privacy: .private)")
            return
        }
        startPipeline(for: recordingId, liveTranscription: result)
    }

    public func startPipeline(for recordingId: RecordingID, liveTranscription: TranscriptionResult) {
        pipelineTask?.cancel()
        activeRecordingId = recordingId
        pipelineGeneration &+= 1

        let generation = pipelineGeneration

        // Self is intentionally captured strongly: PipelineCoordinator is owned by AppAssembler
        // for the app lifetime; the temporary strong cycle resolves when the task completes or is cancelled.
        pipelineTask = Task {
            logger.info("Pipeline START for \(recordingId, privacy: .public)")
            setPipelineState(.diarizing, generation: generation)

            guard let diarizationResult = await runDiarizationPass(
                recordingId: recordingId,
                transcription: liveTranscription,
                generation: generation,
            ) else {
                return
            }

            guard !Task.isCancelled else { return }

            await runSummarizationPass(recordingId: recordingId, transcript: diarizationResult, generation: generation)
        }
    }

    public func startCleanupPass(for recordingId: RecordingID) {
        guard archivePassEnabled else { return }

        cleanupTask?.cancel()
        activeRecordingId = recordingId

        let engine = primaryEngine
        let shouldUnload = physicalMemory < PipelineCoordinator.memoryUnloadThreshold

        cleanupTask = Task {
            onCleanupStateChanged?(.running)
            if shouldUnload, let engine {
                await engine.unloadModel()
            }
            let result = await performCleanupTranscription(recordingId: recordingId)
            if let result {
                onCleanupStateChanged?(.complete(result))
            } else {
                onCleanupStateChanged?(.idle)
            }
        }
    }

    public func runCleanupPass(recordingId: RecordingID) async -> TranscriptionResult? {
        onCleanupStateChanged?(.running)
        let result = await performCleanupTranscription(recordingId: recordingId)
        if let result {
            onCleanupStateChanged?(.complete(result))
            onPipelineStateChanged?(.diarizing)
        } else {
            onCleanupStateChanged?(.idle)
        }
        return result
    }

    private func performCleanupTranscription(recordingId: RecordingID) async -> TranscriptionResult? {
        do {
            let result = try await cleanupTranscribe.transcribeCleanupPass(
                recordingId: recordingId,
                modelId: ModelIDs.cleanupTranscription,
            )
            guard !Task.isCancelled else { return nil }
            guard isActiveRecording(recordingId) else { return nil }
            return result
        } catch {
            if error is CancellationError { return nil }
            let msg = "Cleanup transcription failed: \(error.userFacingMessage)"
            logger.error("\(msg, privacy: .private)")
            onPipelineError?(msg)
            return nil
        }
    }

    private func runDiarizationPass(
        recordingId: RecordingID,
        transcription: TranscriptionResult,
        generation: Int,
    ) async -> DiarizedTranscript? {
        do {
            let result = try await diarizeMeeting.diarize(recordingId: recordingId, transcription: transcription)
            guard !Task.isCancelled else {
                clearStateIfActive(generation: generation)
                return nil
            }
            guard isActiveRecording(recordingId) else {
                clearStateIfActive(generation: generation)
                return nil
            }

            setPipelineState(.summarizing(result), generation: generation)
            return result
        } catch {
            if error is CancellationError { return nil }
            let msg = "Diarization failed: \(error.userFacingMessage)"
            logger.error("\(msg, privacy: .private)")
            onPipelineError?(msg)
            setPipelineState(.failed(msg), generation: generation)
            return nil
        }
    }

    /// Public entry point for external callers (e.g. recovery paths, UI-triggered re-summarization).
    /// Guards on `isActiveRecording` but not on `pipelineGeneration` — callers are responsible
    /// for ensuring the recording is still the active session before invoking.
    public func runSummarizationPass(recordingId: RecordingID, transcript: DiarizedTranscript) async {
        do {
            let result = try await summarizeMeeting.summarize(recordingId: recordingId, transcript: transcript)
            guard !Task.isCancelled else { return }
            guard isActiveRecording(recordingId) else {
                onPipelineStateChanged?(.idle)
                return
            }
            onPipelineStateChanged?(.complete(transcript, result))
        } catch {
            if error is CancellationError { return }
            let msg = "Summarization failed: \(error.userFacingMessage)"
            logger.error("\(msg, privacy: .private)")
            onPipelineError?(msg)
            onPipelineStateChanged?(.failed(msg))
        }
    }

    private func runSummarizationPass(recordingId: RecordingID, transcript: DiarizedTranscript, generation: Int) async {
        do {
            let result = try await summarizeMeeting.summarize(recordingId: recordingId, transcript: transcript)
            guard !Task.isCancelled else {
                clearStateIfActive(generation: generation)
                return
            }
            guard isActiveRecording(recordingId) else {
                clearStateIfActive(generation: generation)
                return
            }
            setPipelineState(.complete(transcript, result), generation: generation)
        } catch {
            if error is CancellationError { return }
            let msg = "Summarization failed: \(error.userFacingMessage)"
            logger.error("\(msg, privacy: .private)")
            onPipelineError?(msg)
            setPipelineState(.failed(msg), generation: generation)
        }
    }

    private func isActiveRecording(_ id: RecordingID) -> Bool {
        activeRecordingId == id
    }

    private func setPipelineState(_ state: PipelineState, generation: Int) {
        if pipelineGeneration == generation {
            onPipelineStateChanged?(state)
        }
    }

    private func clearStateIfActive(generation: Int) {
        if pipelineGeneration == generation {
            onPipelineStateChanged?(.idle)
        }
    }
}

import Foundation

public struct TranscriptionConfig: Sendable, Codable, Equatable {
    public let defaultEngine: TranscriptionEngineKey
    public let fallbackEngine: TranscriptionEngineKey
    public let cleanupModelId: ModelID
    public let archivePassEnabled: Bool

    public static let `default` = TranscriptionConfig(
        defaultEngine: .parakeet,
        fallbackEngine: .whisperkit,
        cleanupModelId: ModelID("distil-whisper_distil-large-v3")
    )

    public init(
        defaultEngine: TranscriptionEngineKey,
        fallbackEngine: TranscriptionEngineKey,
        cleanupModelId: ModelID,
        archivePassEnabled: Bool = true
    ) {
        self.defaultEngine = defaultEngine
        self.fallbackEngine = fallbackEngine
        self.cleanupModelId = cleanupModelId
        self.archivePassEnabled = archivePassEnabled
    }

    // MARK: - Codable (backward-compatible decoding)

    private enum CodingKeys: String, CodingKey {
        case defaultEngine
        case fallbackEngine
        case cleanupModelId
        case archivePassEnabled
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        defaultEngine = try container.decode(TranscriptionEngineKey.self, forKey: .defaultEngine)
        fallbackEngine = try container.decode(TranscriptionEngineKey.self, forKey: .fallbackEngine)
        cleanupModelId = try container.decode(ModelID.self, forKey: .cleanupModelId)
        archivePassEnabled = try container.decodeIfPresent(Bool.self, forKey: .archivePassEnabled) ?? true
    }
}

import Domain
import Foundation
@testable import MLInfrastructure
import Testing

// MARK: - WhisperKitPlugin Unload Tests
//
// Task-2: Implement unloadModel() on WhisperKitPlugin
//
// These tests call unloadModel() — a method that does not yet exist on
// WhisperKitPlugin. The resulting compilation error IS the RED state.
// Each test asserts a specific observable outcome after unloadModel() is called,
// so the tests remain meaningful once GREEN is implemented.

// MARK: - Tag Declarations

extension Tag {
    @Tag static var prop001: Tag
    @Tag static var prop002: Tag
    @Tag static var prop003: Tag
    @Tag static var prop004: Tag
}

// MARK: - AC1: unloadModel() sets internal whisperKit reference to nil
//
// Observable proxy: after unloadModel(), isReady() must return false because
// isReady() is implemented as `whisperKit != nil`. If whisperKit is not nil,
// isReady() would return true — so false proves the reference was cleared.

extension NativeLibraryTests {
    @Suite("task-2 — PROP-001: unloadModel sets whisperKit nil", .serialized)
    struct Task2AC1Tests {
        // Traceability: AC1 → test_ac1_whisperkitplugin_unloadmodel_sets_internal_whisperkit_refere
        @Test(.tags(.prop001))
        func test_ac1_whisperkitplugin_unloadmodel_sets_internal_whisperkit_refere() async throws {
            // Arrange: fresh plugin (whisperKit is already nil, isReady == false)
            let plugin = WhisperKitPlugin()

            // Act: call unloadModel() — clears any internal whisperKit reference
            // NOTE: This method does not exist yet — compilation failure == RED state.
            await plugin.unloadModel()

            // Assert: whisperKit reference is nil — observable via isReady() == false.
            // If whisperKit were non-nil after unloadModel(), isReady() would return true.
            let ready = await plugin.isReady()
            #expect(ready == false, "isReady() must return false after unloadModel() — proves whisperKit is nil")
        }
    }
}

// MARK: - AC2: unloadModel() sets loadedModelId to nil
//
// Observable proxy: after unloadModel(), calling transcribe() with valid samples
// must throw .modelNotLoaded (not .audioTooShort and not any other error),
// because TranscriptionError.modelNotLoaded is thrown when loadedModelId/whisperKit
// are both nil. A non-nil loadedModelId would not gate the transcription path —
// only whisperKit being nil matters for the throw, but the combination of both
// being nil after unloadModel is the contract.

extension NativeLibraryTests {
    @Suite("task-2 — PROP-002: unloadModel sets loadedModelId nil", .serialized)
    struct Task2AC2Tests {
        // Traceability: AC2 → test_ac2_whisperkitplugin_unloadmodel_sets_loadedmodelid_to_nil
        @Test(.tags(.prop002))
        func test_ac2_whisperkitplugin_unloadmodel_sets_loadedmodelid_to_nil() async throws {
            // Arrange
            let plugin = WhisperKitPlugin()
            let context = TranscriptionContext(modelId: ModelID("openai_whisper-tiny.en"))
            // 3200 samples = 0.2s at 16 kHz — well above any audioTooShort threshold
            let validSamples = [Float](repeating: 0.01, count: 3200)

            // Act: call unloadModel() — must set loadedModelId to nil
            // NOTE: This method does not exist yet — compilation failure == RED state.
            await plugin.unloadModel()

            // Assert: transcribe throws .modelNotLoaded (not .audioTooShort),
            // proving the model-not-loaded path is reached because loadedModelId is nil.
