import Domain
import FluidAudio
import Foundation
import Logging
import Utilities

// MARK: - ParakeetPlugin

/// FluidAudio/Parakeet TDT transcription engine (Apple Silicon optimised).
///
/// ## Thread Safety
/// All mutable state (`asrManager`, `loadedModelId`, `sequenceCounter`) is
/// actor-isolated. `AsrManager` is itself an actor; all calls to it cross
/// isolation boundaries via `await`.
///
/// ## Decoder State
/// A fresh `TdtDecoderState` is created per `transcribe` call, making each
/// invocation stateless. This is appropriate for batch/chunk processing where
/// the caller manages session continuity via `TranscriptionContext`.
///
/// ## warm-up
/// `warmUp()` is a no-op: `AsrManager` prewarms its CoreML models during
/// `initialize` / `loadModels`. No additional pass is needed.
public actor ParakeetPlugin: TranscriptionEngine {
    // MARK: - Actor State

    private var asrManager: AsrManager?
    private var loadedModelId: ModelID?
    private var sequenceCounter = 0
    public private(set) var downloadDelegate: (any ModelDownloadDelegate)?

    private let logger = AppLogger.for(category: "Parakeet")

    // MARK: - Init

    public init() {}

    public func setDownloadDelegate(_ delegate: (any ModelDownloadDelegate)?) {
        downloadDelegate = delegate
    }

    // MARK: - TranscriptionEngine

    public func loadModel(_ modelId: ModelID) async throws {
        if loadedModelId == modelId, asrManager != nil {
            logger.info("Parakeet model already loaded — skipping")
            return
        }

        logger.info("Loading Parakeet model '\(modelId, privacy: .public)'")
        await downloadDelegate?.downloadProgress(
            .init(modelId: modelId, fractionCompleted: 0.0, phase: .downloading)
        )

        do {
            let models = try await withTimeout(TimeoutConfig.modelLoad) {
                try await AsrModels.downloadAndLoad(version: .v3)
            }

            await downloadDelegate?.downloadProgress(
                .init(modelId: modelId, fractionCompleted: 0.6, phase: .compiling)
            )

            let tdtConfig = TdtConfig(blankId: AsrModelVersion.v3.blankId)
            let asrConfig = ASRConfig(
                tdtConfig: tdtConfig,
                encoderHiddenSize: AsrModelVersion.v3.encoderHiddenSize
            )
            let manager = AsrManager(config: asrConfig)
            try await manager.loadModels(models)

            asrManager = manager
            loadedModelId = modelId

            await downloadDelegate?.downloadProgress(
                .init(modelId: modelId, fractionCompleted: 1.0, phase: .ready)
            )
            logger.info("Parakeet model '\(modelId, privacy: .public)' loaded")
        } catch {
            asrManager = nil
            loadedModelId = nil
            let errDesc = String(reflecting: error)
            logger.error("Parakeet load error: \(errDesc, privacy: .private)")
            throw TranscriptionError.modelNotLoaded(underlying: error)
        }
    }

    public func transcribe(
        samples: [Float],
        context: TranscriptionContext
    ) async throws -> Domain.TranscriptionSegment {
        guard !samples.isEmpty else {
            throw TranscriptionError.audioTooShort
        }
        guard let manager = asrManager else {
            throw TranscriptionError.modelNotLoaded(underlying: nil)
        }

        let sid = context.sessionId?.rawValue ?? "none"
        // swiftlint:disable:next line_length
        logger.debug("Parakeet transcribing \(samples.count, privacy: .public) samples | session: \(sid, privacy: .private)")

        let result: ASRResult
        let profiler = HardwareBoundaryProfiler(category: "Performance")
        let token = await profiler.begin("Parakeet Inference")

        do {
            let layers = await manager.decoderLayerCount
            var decoderState = TdtDecoderState.make(decoderLayers: layers)
            result = try await manager.transcribe(samples, decoderState: &decoderState)
            await profiler.end(token)
        } catch {
            await profiler.end(token)
            let errDesc = String(reflecting: error)
            logger.error("Parakeet inference error: \(errDesc, privacy: .private)")
            throw TranscriptionError.inferenceFailed(underlying: error)
        }

        let seqNum = sequenceCounter
        sequenceCounter += 1
        return buildSegment(result: result, context: context, sequenceNumber: seqNum)
    }

    public func isReady() async -> Bool {
        asrManager != nil
    }

    /// No-op: Parakeet models are warm after `AsrManager.loadModels(_:)`.
    public func warmUp() async throws {}

    // MARK: - Private Helpers

    private func buildSegment(
        result: ASRResult,
        context: TranscriptionContext,
        sequenceNumber: Int
    ) -> Domain.TranscriptionSegment {
        let startTime = context.timestampOffset
        let endTime = startTime + result.duration
        let confidence = min(1.0, max(0.0, Double(result.confidence)))

        return Domain.TranscriptionSegment(
            id: .generate(),
            text: result.text,
            startTime: startTime,
            endTime: endTime,
            confidence: confidence,
            isFinal: context.isFinalChunk,
            sequenceNumber: sequenceNumber
        )
    }
}

