import Domain
import Foundation
@testable import MLInfrastructure
import Testing

extension NativeLibraryTests {
    @Suite("ParakeetPlugin — unloadModel", .serialized)
    struct ParakeetPluginUnloadTests {

        @Test("unloadModel sets isReady to false")
        func unloadModelSetsNotReady() async {
            let plugin = ParakeetPlugin()
            await plugin.unloadModel()
            let ready = await plugin.isReady()
            #expect(!ready, "isReady() must return false after unloadModel()")
        }

        @Test("unloadModel clears loadedModelId — transcribe throws modelNotLoaded for valid samples")
        func unloadModelClearsLoadedModelId() async throws {
            let plugin = ParakeetPlugin()
            let context = TranscriptionContext(modelId: ModelID("mlx-community_parakeet-tdt-0.6b-v2"))
            let validSamples = [Float](repeating: 0.01, count: 3200)

            await plugin.unloadModel()

            var threwModelNotLoaded = false
            var threwOther = false
            do {
                _ = try await plugin.transcribe(samples: validSamples, context: context)
            } catch TranscriptionError.modelNotLoaded {
                threwModelNotLoaded = true
            } catch {
                threwOther = true
            }
            #expect(threwModelNotLoaded, "transcribe must throw .modelNotLoaded after unloadModel()")
            #expect(!threwOther, "No other error type should be thrown for valid samples after unloadModel()")
        }

        @Test("repeated unloadModel calls are safe")
        func repeatedUnloadIsIdempotent() async {
            let plugin = ParakeetPlugin()
            await plugin.unloadModel()
            await plugin.unloadModel()
            let ready = await plugin.isReady()
            #expect(!ready, "isReady() must remain false after repeated unloadModel() calls")
        }
    }
}

