import Foundation

/// Centralized application constants to prevent magic strings and manage default values.
public enum AppConstants {
    /// Bundle identifiers and related constants.
    public enum Bundle {
        /// The main bundle identifier. Falls back to a default if unavailable.
        public static var identifier: String {
            Foundation.Bundle.main.bundleIdentifier ?? "app.the-record"
        }
    }

    /// Application directories and path names.
    public enum Paths {
        /// The main application directory name.
        public static let appDirectoryName = "THE RECORD"

        /// The config directory name.
        public static let configDirectoryName = ".therecord"

        /// The config file name.
        public static let configFileName = "config.json"

        /// The recordings directory name.
        public static let recordingsDirectoryName = "recordings"

        /// The DuckDB database file name.
        public static let databaseFileName = "therecord.duckdb"

        /// The DuckDB commitments database file name.
        public static let commitmentsDatabaseFileName = "commitments.duckdb"

        /// The speaker profiles JSON file name.
        public static let speakerProfilesFileName = "speaker-profiles.json"

        /// The local command server socket file name.
        public static let commandServerSocketFileName = "therecord.sock"

        /// The local command server HMAC secret file name.
        public static let commandServerSecretFileName = "therecord-hmac.secret"

        /// HuggingFace Hub cache path relative to application support or home.
        public static let huggingFaceHubPath = "huggingface/hub"

        /// FluidAudio diarization model path.
        public static let fluidAudioDiarizationPath = "FluidAudio/Models/speaker-diarization"

        /// FluidAudio Parakeet model path.
        public static let fluidAudioParakeetPath = "FluidAudio/Models/parakeet-tdt-0.6b-v3"

        /// HuggingFace cache base path relative to home.
        public static let huggingFaceCacheBasePath = ".cache/huggingface/hub"

        /// WhisperKit CoreML snapshots path.
        public static let whisperKitSnapshotsPath = ".cache/huggingface/hub/models--argmaxinc--whisperkit-coreml/snapshots"

        /// Validates and sanitizes a filename or path component to prevent path traversal.
        /// - Parameter component: The path component to sanitize.
        /// - Returns: A sanitized path component. Throws if invalid.
        public static func sanitizePathComponent(_ component: String) throws -> String {
            let sanitized = component.trimmingCharacters(in: .whitespacesAndNewlines)
            if sanitized.isEmpty || sanitized == "." || sanitized == ".." || sanitized.contains("/") || sanitized.contains("\\") {
                throw CocoaError(.fileReadInvalidFileName)
            }
            return sanitized
        }
    }
}

import Domain
import Foundation

/// Canonical directory paths for THE RECORD's local-first storage.
///
/// All path resolution lives here — no other file should independently
/// compute `~/Library/Application Support/THE RECORD/`.
public enum Directories {
    /// `~/Library/Application Support/THE RECORD/`
    public static let appSupport: URL = {
        let base = FileManager.default.urls(
            for: .applicationSupportDirectory,
            in: .userDomainMask
        ).first ?? URL(fileURLWithPath: NSHomeDirectory())
            .appendingPathComponent("Library/Application Support")
        return base.appendingPathComponent(AppConstants.Paths.appDirectoryName, isDirectory: true)
    }()

    /// `~/Library/Application Support/THE RECORD/recordings/`
    public static let recordings: URL = appSupport.appendingPathComponent(AppConstants.Paths.recordingsDirectoryName, isDirectory: true)

    /// Creates the directory at `url` with owner-only permissions (0o700).
    /// Idempotent: tightens existing directory permissions if needed.
    public static func ensureDirectory(at url: URL) throws {
        try FileManager.default.createDirectory(at: url, withIntermediateDirectories: true)
        try FileManager.default.setAttributes(
            [.posixPermissions: 0o700],
            ofItemAtPath: url.path
        )
    }
}

