import Domain
import DuckDB
import Foundation

// MARK: - MigrationStep

/// A single versioned, named schema migration step.
public struct MigrationStep: Sendable {
    /// Human-readable name for logging and diagnostics.
    public let name: String

    /// The schema version the database must be at before this step can run.
    public let fromVersion: Int32

    /// The schema version the database will be at after this step runs successfully.
    public let toVersion: Int32

    /// The migration closure. Receives an open `Connection` and must apply schema changes.
    /// Throwing here will cause the runner to roll back and rethrow as `StorageError.migrationFailed`.
    public let migrate: @Sendable (Connection) throws -> Void

    public init(
        name: String,
        fromVersion: Int32,
        toVersion: Int32,
        migrate: @escaping @Sendable (Connection) throws -> Void
    ) {
        self.name = name
        self.fromVersion = fromVersion
        self.toVersion = toVersion
        self.migrate = migrate
    }
}

// MARK: - DuckDBMigrationRunner

/// Executes versioned, ordered, idempotent schema migrations against a DuckDB connection.
///
/// Schema version is tracked via a `schema_version` table (DuckDB has no PRAGMA user_version).
/// On each `migrate(connection:)` call, only steps whose `fromVersion` matches the current version
/// are applied — already-applied steps are skipped.
///
/// Each step is wrapped in a BEGIN/ROLLBACK transaction. If a step throws, the transaction is
/// rolled back and `StorageError.migrationFailed` is thrown — leaving the schema version unchanged.
public final class DuckDBMigrationRunner: Sendable {

    // MARK: - Public state

    /// Ordered list of migration steps this runner will apply.
    public let steps: [MigrationStep]

    /// The schema version that a fully-migrated database should be at.
    public var currentSchemaVersion: Int32 {
        steps.last?.toVersion ?? 0
    }

    /// Versions applied during the most recent `migrate(connection:)` call (ascending order).
    /// Protected by the serial nature of `migrate` — callers must `await` before reading.
    public nonisolated(unsafe) private(set) var appliedVersions: [Int32] = []

    // MARK: - Init

    /// Creates a runner with an explicit set of steps (primarily for testing).
    public init(steps: [MigrationStep]) {
        self.steps = steps
    }

    /// Creates a runner with the production migration plan.
    public convenience init() {
        self.init(steps: DuckDBMigrationRunner.productionSteps)
    }

    // MARK: - migrate

    /// Applies all pending migrations to `connection` in ascending version order.
    ///
    /// Each step is wrapped in an explicit transaction. On failure the transaction is rolled
    /// back and `StorageError.migrationFailed` is thrown. The `user_version` pragma is updated
    /// inside the same transaction so it stays in sync.
    ///
    /// Calling `migrate` again after a successful run is a no-op.
    public func migrate(connection: Connection) throws {
        var applied: [Int32] = []

        for step in steps {
            let currentVersion = try readUserVersion(connection: connection)

            // Skip steps that have already been applied.
            guard currentVersion == step.fromVersion else {
                continue
            }

            // Each step runs inside a transaction so partial DDL can be rolled back.
            do {
                try connection.execute("BEGIN TRANSACTION")
                try step.migrate(connection)
                try connection.execute("PRAGMA user_version = \(step.toVersion)")
                try connection.execute("COMMIT")
                applied.append(step.toVersion)
            } catch {
                // Roll back the partial work and re-throw as a StorageError.
                try? connection.execute("ROLLBACK")
                throw StorageError.migrationFailed(underlying: AnyError(error))
            }
        }

        appliedVersions = applied
    }

    // MARK: - Helpers

    private func readUserVersion(connection: Connection) throws -> Int32 {
        let result = try connection.query("PRAGMA user_version")
        let col = result[0].cast(to: Int32.self)
        guard let version = col[0] else {
            throw StorageError.migrationFailed(underlying: AnyError(
                NSError(domain: "DuckDBMigrationRunner", code: -1,
                        userInfo: [NSLocalizedDescriptionKey: "PRAGMA user_version returned nil"])
            ))
        }
        return version
    }
}

// MARK: - AnyError (Sendable wrapper)

/// Wraps any non-Sendable error to satisfy `StorageError.migrationFailed(underlying:)`.
private struct AnyError: Error, Sendable {
    let message: String
    init(_ error: any Error) {
        self.message = error.localizedDescription
    }
}

// MARK: - Production migration plan

extension DuckDBMigrationRunner {
    /// The ordered list of production schema migrations.
    ///
    /// Version history:
    ///   v0 → v1 : Create core tables (recordings, diarized_segments, summaries, meeting_notes,
    ///             commitments, inference_telemetry) + indexes
    ///   v1 → v2 : Add `is_pending` column to recordings
    ///   v2 → v3 : Add `word_timings` column to diarized_segments
    ///   v3 → v4 : Add `cleaned_mic_audio_url` column to recordings (epic-28)
    static let productionSteps: [MigrationStep] = [
        MigrationStep(
            name: "v0→v1: create-core-tables",
            fromVersion: 0,
            toVersion: 1,
            migrate: { conn in
                try conn.execute(DuckDBSQL.createRecordings)
                try conn.execute(DuckDBSQL.createSegments)
                try conn.execute(DuckDBSQL.createSummaries)
                try conn.execute(DuckDBSQL.createMeetingNotes)
                try conn.execute(DuckDBSQL.createCommitmentsTable)
                try conn.execute(DuckDBSQL.createInferenceTelemetry)
                try conn.execute(DuckDBSQL.createRecordingsIndex)
                try conn.execute(DuckDBSQL.createCommitmentsStatusIndex)
                try conn.execute(DuckDBSQL.createCommitmentsMeetingIndex)
            }
        ),
        MigrationStep(
            name: "v1→v2: add-is-pending-column",
            fromVersion: 1,
            toVersion: 2,
            migrate: { conn in
                try conn.execute(DuckDBSQL.addIsPendingColumn)
            }
        ),
        MigrationStep(
            name: "v2→v3: add-word-timings-column",
            fromVersion: 2,
            toVersion: 3,
            migrate: { conn in
                try conn.execute(DuckDBSQL.addWordTimingsColumn)
            }
        ),
        MigrationStep(
            name: "v3→v4: add-cleaned-mic-audio-url-column",
            fromVersion: 3,
            toVersion: 4,
            migrate: { conn in
                try conn.execute(DuckDBSQL.addCleanedMicAudioUrlColumn)
            }
        ),
        MigrationStep(
            name: "v4→v5: add-needs-retranscription-column",
            fromVersion: 4,
            toVersion: 5,
            migrate: { conn in
                try conn.execute(DuckDBSQL.addNeedsRetranscriptionColumn)
            }
        ),
        MigrationStep(
            name: "v5->v6: add-transcript-draft-column",
            fromVersion: 5,
            toVersion: 6,
            migrate: { conn in
                try conn.execute(DuckDBSQL.addTranscriptDraftColumn)
            }
        ),
    ]
}

